class Solution {
public:
    vector<int> intersection(vector<vector<int>>& nums) {
        vector<int> count(1001, 0);
        for (auto& arr : nums) {
            for (int x : arr) {
                count[x]++;
            }
        }
        vector<int> res;
        for (int v = 1; v <= 1000; v++) {
            if (count[v] == (int)nums.size()) {
                res.push_back(v);
            }
        }
        return res;
    }
};

