var intersection = function(nums) {
    let common = new Set(nums[0]);
    for (let i = 1; i < nums.length; i++) {
        const next = new Set();
        for (const x of nums[i]) {
            if (common.has(x)) next.add(x);
        }
        common = next;
    }
    return [...common].sort((a, b) => a - b);
};
